<?php
require_once __DIR__.'/../config/auth.php';require_role('owner');$pageTitle='Laporan Penjualan';
$from=(string)($_GET['from']??date('Y-m-01'));$to=(string)($_GET['to']??date('Y-m-d'));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from))$from=date('Y-m-01');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to))$to=date('Y-m-d');$menuId=(int)($_GET['menu_id']??0);$cashierId=(int)($_GET['kasir_id']??0);
$where='DATE(o.created_at) BETWEEN ? AND ? AND o.status_pesanan<>\'Dibatalkan\' AND o.status_bayar=\'Lunas\'';$args=[$from,$to];if($menuId){$where.=' AND oi.menu_id=?';$args[]=$menuId;}if($cashierId){$where.=' AND o.kasir_id=?';$args[]=$cashierId;}
$sql="SELECT o.id,o.kode_pesanan,o.created_at,o.nama_pelanggan,o.total,o.status_bayar,o.status_pesanan,o.metode_bayar,u.nama kasir,oi.nama_menu,oi.qty,oi.harga,oi.qty*oi.harga line_total FROM orders o LEFT JOIN users u ON u.id=o.kasir_id JOIN order_items oi ON oi.order_id=o.id WHERE $where ORDER BY o.created_at DESC,oi.id";$st=$pdo->prepare($sql);$st->execute($args);$rows=$st->fetchAll();
if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="kopiah-laporan-'.$from.'-'.$to.'.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Kode Pesanan','Tanggal','Pelanggan','Menu','Qty','Harga Satuan','Subtotal Item','Status Pembayaran','Status Pesanan','Metode Bayar','Kasir']);$safeCsv=fn($v)=>preg_match('/^[=+@\-\t\r]/',(string)$v)?"'".(string)$v:$v;foreach($rows as $r)fputcsv($out,array_map($safeCsv,[$r['kode_pesanan'],$r['created_at'],$r['nama_pelanggan'],$r['nama_menu'],$r['qty'],$r['harga'],$r['line_total'],$r['status_bayar'],$r['status_pesanan'],$r['metode_bayar'],$r['kasir']??'Online']));fclose($out);exit;}
$sumWhere='DATE(o.created_at) BETWEEN ? AND ? AND o.status_pesanan<>\'Dibatalkan\' AND o.status_bayar=\'Lunas\'';$sumArgs=[$from,$to];if($menuId){$sumWhere.=' AND EXISTS (SELECT 1 FROM order_items oi2 WHERE oi2.order_id=o.id AND oi2.menu_id=?)';$sumArgs[]=$menuId;}if($cashierId){$sumWhere.=' AND o.kasir_id=?';$sumArgs[]=$cashierId;}$sumSql="SELECT COUNT(*) orders_count,COALESCE(SUM(o.total),0) sum_total FROM orders o WHERE $sumWhere";$ss=$pdo->prepare($sumSql);$ss->execute($sumArgs);$summary=$ss->fetch();$menus=dbq('SELECT id,nama FROM menus ORDER BY nama')->fetchAll();$cashiers=dbq("SELECT id,nama FROM users WHERE role='kasir' ORDER BY nama")->fetchAll();
require __DIR__.'/../includes/admin-header.php'; ?>
<div class="no-print card p-5"><form method="get" class="grid sm:grid-cols-2 xl:grid-cols-5 gap-3 items-end"><div><label class="field-label">Dari tanggal</label><input class="field" type="date" name="from" value="<?= h($from) ?>"></div><div><label class="field-label">Sampai tanggal</label><input class="field" type="date" name="to" value="<?= h($to) ?>"></div><div><label class="field-label">Filter menu</label><select class="field" name="menu_id"><option value="0">Semua menu</option><?php foreach($menus as $m):?><option value="<?= (int)$m['id'] ?>" <?= $menuId===(int)$m['id']?'selected':'' ?>><?= h($m['nama']) ?></option><?php endforeach;?></select></div><div><label class="field-label">Filter kasir</label><select class="field" name="kasir_id"><option value="0">Semua kasir</option><?php foreach($cashiers as $c):?><option value="<?= (int)$c['id'] ?>" <?= $cashierId===(int)$c['id']?'selected':'' ?>><?= h($c['nama']) ?></option><?php endforeach;?></select></div><button class="btn btn-coffee">Terapkan filter</button></form><div class="flex flex-wrap gap-3 mt-4"><a class="btn btn-light !py-2" href="?<?= h(http_build_query(['from'=>$from,'to'=>$to,'menu_id'=>$menuId,'kasir_id'=>$cashierId,'export'=>'csv'])) ?>">Export Excel (CSV)</a><button class="btn btn-light !py-2" type="button" onclick="window.print()">Cetak / Simpan PDF</button></div></div>
<div class="grid sm:grid-cols-3 gap-4 mt-5"><div class="card p-5"><p class="text-xs text-coffee/55">Jumlah pesanan</p><p class="font-serif text-2xl mt-2"><?= (int)$summary['orders_count'] ?></p></div><div class="card p-5"><p class="text-xs text-coffee/55">Omzet sesuai filter</p><p class="font-serif text-2xl mt-2"><?= money($summary['sum_total']) ?></p><p class="text-xs text-coffee/45 mt-1">hanya transaksi lunas; pesanan batal tidak dihitung</p></div><div class="card p-5"><p class="text-xs text-coffee/55">Baris item</p><p class="font-serif text-2xl mt-2"><?= count($rows) ?></p></div></div>
<section class="card p-5 mt-5"><div class="flex items-end justify-between gap-3"><div><h2 class="font-serif text-2xl">Detail penjualan</h2><p class="text-xs text-coffee/55 mt-1"><?= h(date('d M Y',strtotime($from))) ?> – <?= h(date('d M Y',strtotime($to))) ?></p></div></div><div class="table-wrap mt-4"><table class="admin-table"><thead><tr><th>Pesanan</th><th>Waktu / Pelanggan</th><th>Menu</th><th>Qty</th><th>Harga</th><th>Subtotal item</th><th>Total pesanan</th><th>Bayar / Kasir</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?= h($r['kode_pesanan']) ?></b><span class="block text-xs text-coffee/55"><?= h($r['status_pesanan']) ?></span></td><td><?= h(date('d/m/Y H:i',strtotime($r['created_at']))) ?><span class="block text-xs text-coffee/55"><?= h($r['nama_pelanggan']) ?></span></td><td><?= h($r['nama_menu']) ?></td><td><?= (int)$r['qty'] ?></td><td><?= money($r['harga']) ?></td><td><?= money($r['line_total']) ?></td><td><?= money($r['total']) ?></td><td><span class="block"><?= h($r['status_bayar']) ?></span><span class="text-xs text-coffee/55"><?= h($r['metode_bayar']) ?> · <?= h($r['kasir']??'Online') ?></span></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="8">tidak ada transaksi pada filter ini.</td></tr><?php endif;?></tbody></table></div><p class="text-xs text-coffee/50 mt-4">PDF: gunakan tombol cetak lalu pilih “Save as PDF” pada dialog print browser. CSV dapat dibuka di Excel atau Google Sheets.</p></section>
<style>@media print{body{background:white!important}.no-print,aside,header,footer{display:none!important}.md\:ml-64{margin:0!important}.card{box-shadow:none!important;break-inside:avoid}.admin-table{font-size:9px}.admin-table th,.admin-table td{padding:4px}}</style><?php require __DIR__.'/../includes/admin-footer.php'; ?>
